{"results": [{"id": "FAM:SF-APPS-024", "label": "Study family SF-APPS-024: DRIVE-as-BEST counter vs constrained mix", "score": 1.143, "reached_via": ["FAM:SF-APPS-023 auto_related_family (repeat_order_unknown) FAM:SF-APPS-024", "FAM:SF-APPS-023 auto_related_family (repeat_order_unknown) FAM:SF-APPS-024"], "attributes": {"observed_research_question": "DRIVE-as-BEST counter vs constrained mix", "auto_outcome_status": "untestable", "observed_hypothesis": "When BEST=DRIVE (counter_h2_n>=5), observed DRIVE H2 PPP beats a feasibility-constrained baseline.", "observed_result": "A mean=1.178 vs B_game 1.236 (gap=-0.058, p=0.6069) vs B_fixed 1.244 (gap=-0.066, p=0.2175) vs coach default C 1.134 (gap=+0.043, p=0.3052). MDE at 80% power ~0.180 PPP (SD~0.34).", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Observed gap -0.066 is below MDE 0.180; n=44 cannot distinguish a true null from an effect up to 0.18 PPP.", "observed_sample_and_power": "n=44; MDE 0.180 PPP at 80% power (SD~0.34); 0.265 if SD~0.5", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:low_power_large_MDE"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 1.135, "reached_via": ["FAM:SF-APPM-022 auto_related_family (repeated_by_later_family) FAM:SF-APPA-050", "FAM:SF-APPM-022 auto_related_family (repeat_of_earlier_family) FAM:SF-APPA-050"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 1.135, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-022 (0.76)", "request matches RQC:RQC-016 (0.76); FAM:SF-APPM-022 auto_addresses_question RQC:RQC-016"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-050"}]}, {"id": "FAM:SF-APPM-055", "label": "Study family SF-APPM-055: Three-level counter ranking: population vs team-specific vs matchup", "score": 1.125, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-055 (0.75)", "request matches RQC:RQC-021 (0.75); FAM:SF-APPM-055 auto_addresses_question RQC:RQC-021"], "attributes": {"observed_research_question": "Three-level counter ranking: population vs team-specific vs matchup", "auto_outcome_status": "inconclusive", "observed_hypothesis": "The best counter after a suppressed play type is stable from population (L1) to team (L2) to matchup (L3); otherwise the playsheet should not use a league default.", "observed_result": "L1 (first run): after DRIVE best=CUT 1.261 vs PNR 1.132 (spread +0.129, CUT n_mu=5 PIVOT_WINS); after PNR best=TRANSITION 1.271 (n=35); after PULL_UP best=CUT 1.370 (n=5). L2 MIA disagrees with L1 on DRIVE (L2 best=PNR n [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_sample_and_power": "L1 n_mu 5 to 696; playoff n_matchups 4 to 44", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-023", "label": "Study family SF-APPS-023: System BEST vs constrained league mix (non-CUT matchup-specificity test)", "score": 0.762, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-023 (0.76)"], "attributes": {"observed_research_question": "System BEST vs constrained league mix (non-CUT matchup-specificity test)", "auto_outcome_status": "rejected", "observed_hypothesis": "Matchup-specific (non-CUT) BEST counters beat a feasibility-weighted league mix that ignores game state.", "observed_result": "All BEST vs mix: 1.481 vs 1.212, gap=+0.269, p=0.0000, n=283. Non-CUT BEST vs mix: 1.216 vs 1.206, gap=+0.010, p=0.1709, n=136. L3_MATCHUP non-CUT: gap=+0.001, p=0.3277, n=47. BEST vs AVOID gap=+0.692, p=0.0000, n=169. 1 [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Key non-CUT test gap=+0.010, p=0.1709, n=136; H2H L3 non-CUT gap=+0.001, p=0.3277. Headline A vs B is CUT-driven.", "observed_sample_and_power": "n=136 non-CUT; n=47 L3 non-CUT"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPM-054", "label": "Study family SF-APPM-054: Playoff adaptation-pair sustainability (12 pairs x 74 matchups)", "score": 0.751, "reached_via": ["request matches RQC:RQC-021 (0.75); FAM:SF-APPM-054 auto_addresses_question RQC:RQC-021", "FAM:SF-APPM-055 auto_related_family (record_link_related_to) FAM:SF-APPM-054"], "attributes": {"observed_research_question": "Playoff adaptation-pair sustainability (12 pairs x 74 matchups)", "auto_outcome_status": "rejected", "observed_hypothesis": "Pivoting to a listed counter after suppression sustains higher PPP than not pivoting, consistently across playoff matchups.", "observed_result": "10/12 pairs CONSISTENT and within 0.10 of non-pivot (no PIVOT_WINS). PNR->PULL_UP sustained 1.069 vs non_pivot 1.224 (n_matchups=9) PIVOT_LOSES. DRIVE->PULL_UP 1.101 vs 1.217 (n=5) PIVOT_LOSES. Largest positive pair in t [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Population deltas mostly |d|<0.10; two pairs with enough signal are PIVOT_LOSES (pivot worse than staying).", "observed_sample_and_power": "n=74 matchups; pair n_matchups 5 to 44"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPM-033"}]}, {"id": "FAM:SF01", "label": "Study family SF01: Suppression is not regression to mean: matched-control excess", "score": 0.742, "reached_via": ["request matches the question or hypothesis of FAM:SF01 (0.74)"], "attributes": {"observed_research_question": "Suppression is not regression to mean: matched-control excess", "auto_outcome_status": "supported", "observed_hypothesis": "The H1-to-H2 PPP drop after a trigger exceeds the drop of a matched control, beyond what RTM predicts.", "observed_result": "PO C: excess +0.680 [0.619, 0.740], n=534, t=22.11; RTM pred 0.097 of 0.626 drop (15.5%), excess 0.529. Full graph unconstrained +0.628 n=9,900 then Z1+Z2 +0.625 n=9,111. H1-balanced caliper 0.10 +0.408 [0.378, 0.438], 1 [cut; read_family for the full text]", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Excess drops from +0.625 unconstrained to +0.408 when balanced on H1 PPP, but the cluster CI excludes 0; Z1+Z2 moved excess only +0.004 vs pre-fix +0.404.", "observed_verdict": "supported", "auto_confidence": "high (1.0)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 0.486, "reached_via": ["request matches RQC:RQC-103 (0.77); FAM:SF-CHT-039 auto_addresses_question RQC:RQC-103"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-012", "label": "Study family SF-APPS-012: Defensive PPP allowed and possession share, RS vs playoffs", "score": 0.473, "reached_via": ["request matches RQC:RQC-079 (0.75); FAM:SF-APPS-012 auto_addresses_question RQC:RQC-079"], "attributes": {"observed_research_question": "Defensive PPP allowed and possession share, RS vs playoffs", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Playoff defenses suppress DRIVE more than RS defenses (both lower PPP allowed and lower share).", "observed_result": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test; PNR share jump of +12.1pp may reflect tagging differences.", "observed_sample_and_power": "25 teams", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "25 defensive teams, min 30 poss per cell; RS vs playoff PPP allowed and opponent possession share by PT.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPS-032", "label": "Study family SF-APPS-032: CUT depletion / decay hypothesis (feasibility, not efficiency)", "score": 0.381, "reached_via": ["FAM:SF-APPS-023 auto_related_family (record_link_related_to) FAM:SF-APPS-032"], "attributes": {"observed_research_question": "CUT depletion / decay hypothesis (feasibility, not efficiency)", "auto_outcome_status": "rejected", "observed_hypothesis": "CUT PPP decays across successive H2 runs, so the playsheet should rotate off CUT to SPOT_UP.", "observed_result": "CUT PPP stable 1.60-1.71 for runs 1-5 (all n>=14); runs 6+ n=4/2/0. 62.0% of team-halves never crossed below SPOT_UP (n=405). Depletion-adjusted rho -0.0415 vs baseline -0.2737 (degraded 0.2322). DP -6.7 pts/100 vs stati [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No efficiency cliff; constraint is opportunity (~3-5 CUT per half). DP was built on fabricated decay.", "observed_sample_and_power": "311 games; CUT runs 6+ essentially unobserved", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}], "n_results": 10}

Stage 2. Using the retrieval result above (follow-up tools are allowed within the tool budget), complete steps 4 to 9
and reply with the final action. Output schema (all fields required):
{
 "research_concepts": [
  "concept"
 ],
 "methodological_questions": [
  "question"
 ],
 "historical_evidence": [
  {
   "id": "identifier of a record returned by a tool",
   "status_as_recorded": "outcome status exactly as stated in the record (supported | rejected | inconclusive | untestable | artifact | not a hypothesis test | no result recorded)",
   "finding": "what the record states, in its own terms"
  }
 ],
 "failed_approaches": [
  {
   "id": "identifier of a returned record",
   "what_failed": "approach",
   "why": "failure mechanism or limitation as recorded"
  }
 ],
 "evidence_establishes": [
  "what the retrieved evidence establishes for this question"
 ],
 "evidence_does_not_establish": [
  "what it leaves open or cannot show"
 ],
 "own_inferences": [
  "your inference, not stated in any record"
 ],
 "uncertainties": [
  "uncertainty or missing information"
 ],
 "historical_effect": {
  "changed_decision": "yes | no | no_historical_evidence",
  "explanation": "whether and how the historical evidence changed the decision"
 },
 "testability": {
  "p_testable": "number in [0,1]: probability the question can be answered with the stated data at useful power",
  "blocking_constraints": [
   {
    "code": "one of RISK_CODES",
    "text": "string"
   }
  ]
 },
 "prior_work": {
  "already_answered": "yes | partly | no | unknown",
  "cited": [
   "identifiers of prior work relied on"
  ],
  "summary": "string"
 },
 "risks": [
  {
   "code": "one of RISK_CODES",
   "text": "string"
  }
 ],
 "predicted_outcome": {
  "supported": "probability",
  "rejected": "probability",
  "untestable": "probability",
  "artifact": "probability",
  "uncertain": "probability"
 },
 "decision": "proceed | proceed_with_changes | do_not_proceed",
 "design": {
  "estimand": "string",
  "unit": "string",
  "sample": "string",
  "power": "string",
  "controls": "string",
  "falsification": "string",
  "multiplicity": "string",
  "decision_rule": "string",
  "data_version": "string"
 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).
